INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1850, 'show', '/ʃoʊ/', 'verb', '{"zh-TW":["展示；顯示"],"en":["to make visible","to demonstrate"]}', NULL, 'show up / trade show', '[{"en":"The data shows a clear trend.","zh-TW":"數據顯示了明確的趨勢。"},{"en":"We will attend the trade show next month.","zh-TW":"我們下個月會參加展覽會。"}]', '{"verb":"show","noun":"show","noun2":"showroom"}', NULL, 1, 1850),
(1851, 'showcase', '/ˈʃoʊkeɪs/', 'noun, verb', '{"zh-TW":["展示；陳列","展示"],"en":["a display or exhibition","to exhibit or present"]}', NULL, 'showcase products / showcase talent / showcase innovation', '[{"en":"The event showcases the latest industry innovations.","zh-TW":"活動展示了最新的產業創新。"},{"en":"We need a platform to showcase our work.","zh-TW":"我們需要一個平台來展示我們的工作。"}]', '{"noun":"showcase","verb":"showcase"}', NULL, 3, 1851),
(1852, 'shower', '/ˈʃaʊər/', 'noun', '{"zh-TW":["陣雨；淋浴"],"en":["a brief fall of rain","a device for washing the body"]}', '{"root":{"text":"shower","meaning":"brief rain (短雨)"},"logic":"指短暫的降雨或用水沖洗。"}', 'rain shower / take a shower / scattered showers', '[{"en":"Scattered showers are expected this afternoon.","zh-TW":"今天下午預計會有零星陣雨。"},{"en":"I take a shower every morning.","zh-TW":"我每天早上淋浴。"}]', '{"adjective":"showery"}', NULL, 2, 1852),
(1853, 'shrink', '/ʃrɪŋk/', 'verb', '{"zh-TW":["縮小；萎縮"],"en":["to become smaller in size or amount"]}', NULL, 'shrink in size / shrink the budget / profit margins shrink', '[{"en":"The economy shrank by 2% last quarter.","zh-TW":"上季度經濟萎縮了2%。"},{"en":"Rising costs have shrunk profit margins.","zh-TW":"成本上升壓縮了利潤率。"}]', '{"noun":"shrinkage","verb":"shrink"}', NULL, 2, 1853),
(1854, 'side', '/saɪd/', 'noun', '{"zh-TW":["邊；方面"],"en":["a position to the left or right","an aspect"]}', NULL, 'on the side / side effect', '[{"en":"She runs a business on the side.","zh-TW":"她兼營一項副業。"},{"en":"Consider both sides of the argument.","zh-TW":"考慮論點的兩面。"}]', '{"noun":"side","adjective":"side","noun2":"sidebar"}', NULL, 1, 1854),
(1855, 'sign', '/saɪn/', 'noun, verb', '{"zh-TW":["標誌；跡象","簽署；簽名"],"en":["an indication or symbol","to write one''s name on a document"]}', NULL, 'sign a contract / sign of progress / warning sign', '[{"en":"Both parties signed the agreement today.","zh-TW":"雙方今天簽署了協議。"},{"en":"There are signs of economic recovery.","zh-TW":"有經濟復甦的跡象。"}]', '{"noun":"sign, signature, signal","verb":"sign, signal"}', NULL, 1, 1855),
(1856, 'significant', '/sɪɡˈnɪfɪkənt/', 'adjective', '{"zh-TW":["重要的；顯著的","重大的；顯著的"],"en":["large enough to be noticed or have an effect","large or important enough to have an effect"]}', '{"root":{"text":"sign","meaning":"mark (標記)"},"suffix":{"text":"-ificant","meaning":"making (造成)"},"logic":"造成明顯標記的，即「顯著的」。"}', 'significant improvement / significant difference / statistically significant; significant improvement / significant impact / statistically significant', '[{"en":"There has been a significant improvement in sales.","zh-TW":"銷售額有了顯著改善。"},{"en":"This is a significant achievement.","zh-TW":"這是一項重大成就。"},{"en":"There has been a significant increase in sales.","zh-TW":"銷售額有了顯著的增長。"},{"en":"The new policy made a significant impact.","zh-TW":"新政策產生了重大影響。"}]', '{"noun":"significance","adverb":"significantly","adjective":"significant, insignificant"}', NULL, 4, 1856),
(1857, 'similar', '/ˈsɪmɪlər/', 'adjective', '{"zh-TW":["相似的；類似的"],"en":["resembling without being identical"]}', NULL, 'similar to / similar results / in a similar way', '[{"en":"Our products are similar to theirs in quality.","zh-TW":"我們的產品在品質上與他們的相似。"},{"en":"We faced a similar problem last year.","zh-TW":"去年我們面臨了類似的問題。"}]', '{"noun":"similarity","adjective":"similar","adverb":"similarly"}', NULL, 3, 1857),
(1858, 'simple', '/ˈsɪmpəl/', 'adjective', '{"zh-TW":["簡單的"],"en":["easy to understand or do"]}', NULL, 'keep it simple / simple solution', '[{"en":"Keep the design simple and clean.","zh-TW":"保持設計簡潔。"},{"en":"There is a simple solution to this.","zh-TW":"這有一個簡單的解決辦法。"}]', '{"adjective":"simple","adverb":"simply","verb":"simplify","noun":"simplicity"}', NULL, 2, 1858),
(1859, 'simplify', '/ˈsɪmplɪfaɪ/', 'verb', '{"zh-TW":["簡化"],"en":["to make something easier to understand or do"]}', '{"suffix":{"text":"-ify","meaning":"使..."}}', 'simplify the process / simplify procedures', '[{"en":"We simplified the application process.","zh-TW":"我們簡化了申請流程。"},{"en":"The new software simplifies data management.","zh-TW":"新軟體簡化了資料管理。"}]', '{"noun":"simplification, simplicity","verb":"simplify","adjective":"simple"}', NULL, 3, 1859),
(1860, 'simulate', '/ˈsɪmjuleɪt/', 'verb', '{"zh-TW":["模擬；模仿"],"en":["to imitate or reproduce conditions"]}', NULL, 'simulate conditions / simulate a scenario', '[{"en":"The software can simulate real-world conditions.","zh-TW":"這個軟體可以模擬真實世界的條件。"},{"en":"They simulated an emergency drill.","zh-TW":"他們模擬了一次緊急演練。"}]', '{"noun":"simulation, simulator","verb":"simulate","adjective":"simulated"}', NULL, 3, 1860),
(1861, 'simultaneous', '/ˌsaɪmlˈteɪniəs/', 'adjective', '{"zh-TW":["同時的；同步的"],"en":["occurring at the same time"]}', NULL, 'simultaneous translation / simultaneous events', '[{"en":"The event will have simultaneous translation.","zh-TW":"活動將提供同步翻譯。"},{"en":"Both teams made simultaneous announcements.","zh-TW":"兩個團隊同時發布了公告。"}]', '{"noun":"simultaneity","adjective":"simultaneous","adverb":"simultaneously"}', NULL, 4, 1861),
(1862, 'sincere', '/sɪnˈsɪr/', 'adjective', '{"zh-TW":["真誠的"],"en":["free from pretense; genuine"]}', '{"root":{"text":"sincer","meaning":"pure/clean (純淨)"},"logic":"源自拉丁語 sincerus（純淨的），指不虛偽的。"}', 'sincere apology / sincere gratitude', '[{"en":"She offered a sincere apology.","zh-TW":"她表達了真誠的歉意。"},{"en":"He is sincere in his desire to help.","zh-TW":"他真心想幫忙。"}]', '{"noun":"sincerity","adverb":"sincerely"}', NULL, 3, 1862),
(1863, 'sit', '/sɪt/', 'verb', '{"zh-TW":["坐"],"en":["to rest in a seated position"]}', NULL, 'sit down / sit in on', '[{"en":"Please sit down and make yourself comfortable.","zh-TW":"請坐下來放輕鬆。"},{"en":"May I sit in on the meeting?","zh-TW":"我可以旁聽這個會議嗎？"}]', '{"verb":"sit","noun":"seat","noun2":"sitting"}', NULL, 1, 1863),
(1864, 'site', '/saɪt/', 'noun', '{"zh-TW":["地點；場所","網站"],"en":["a place where something is located","a website"]}', NULL, 'construction site / on-site / website', '[{"en":"The construction site will be inspected tomorrow.","zh-TW":"施工現場明天將接受檢查。"},{"en":"Please visit our website for more information.","zh-TW":"請訪問我們的網站了解更多資訊。"}]', '{"noun":"site"}', NULL, 1, 1864),
(1865, 'situate', '/ˈsɪtʃueɪt/', 'verb', '{"zh-TW":["使位於；使處於"],"en":["to put in a certain position or context"]}', NULL, 'situated in / favorably situated', '[{"en":"The office is situated in the city center.","zh-TW":"辦公室位於市中心。"},{"en":"The company is well situated for growth.","zh-TW":"公司處於有利的成長位置。"}]', '{"noun":"situation","verb":"situate","adjective":"situated"}', NULL, 3, 1865),
(1866, 'size', '/saɪz/', 'noun', '{"zh-TW":["大小；規模","尺寸；大小"],"en":["how big or small something is","how large or small something is"]}', '{"root":{"text":"size","meaning":"measure (量度)"},"logic":"源自古法語 sise，指物品的量度。"}', 'market size / full-size; what size / size chart / one size fits all', '[{"en":"The market size is estimated at $5 billion.","zh-TW":"市場規模估計為50億美元。"},{"en":"What size do you need?","zh-TW":"你需要什麼尺寸？"},{"en":"What size do you wear?","zh-TW":"你穿什麼尺寸？"},{"en":"This shirt comes in three sizes.","zh-TW":"這件襯衫有三種尺寸。"}]', '{"noun":"size","adjective":"sizable","verb":"size","adjective2":"oversized"}', NULL, 1, 1866),
(1867, 'skeptical', '/ˈskeptɪkl/', 'adjective', '{"zh-TW":["懷疑的；持懷疑態度的"],"en":["not easily convinced; having doubts"]}', NULL, 'skeptical about / remain skeptical / highly skeptical', '[{"en":"Investors remain skeptical about the company''s recovery plan.","zh-TW":"投資者對公司的復甦計畫持懷疑態度。"},{"en":"She was skeptical of the proposal''s feasibility.","zh-TW":"她對提案的可行性持懷疑態度。"}]', '{"noun":"skepticism, skeptic","adjective":"skeptical"}', NULL, 3, 1867),
(1868, 'skepticism', '/ˈskeptɪsɪzəm/', 'noun', '{"zh-TW":["懷疑論；懷疑態度"],"en":["a doubting attitude toward claims"]}', NULL, 'healthy skepticism / meet with skepticism / express skepticism', '[{"en":"The proposal was met with skepticism from investors.","zh-TW":"該提案遭到投資者的質疑。"},{"en":"A healthy skepticism is important in business decisions.","zh-TW":"在商業決策中保持健康的懷疑態度很重要。"}]', '{"noun":"skepticism, skeptic","adjective":"skeptical"}', NULL, 4, 1868),
(1869, 'sketch', '/sketʃ/', 'noun', '{"zh-TW":["素描；草圖"],"en":["a rough drawing made quickly"]}', '{"root":{"text":"sketch","meaning":"quick drawing (速寫)"},"logic":"源自荷蘭語 schets（快速繪畫）。"}', 'pencil sketch / rough sketch', '[{"en":"She did a quick sketch of the building.","zh-TW":"她快速畫了一張建築物的草圖。"},{"en":"The designer showed us several sketches.","zh-TW":"設計師給我們看了幾張草圖。"}]', '{"verb":"sketch","adjective":"sketchy"}', NULL, 2, 1869),
(1870, 'skill', '/skɪl/', 'noun', '{"zh-TW":["技能；技巧"],"en":["the ability to do something well"]}', NULL, 'communication skills / skill set / develop skills', '[{"en":"Employees need to develop new skills regularly.","zh-TW":"員工需要定期發展新技能。"},{"en":"Strong leadership skills are essential for this role.","zh-TW":"這個職位需要很強的領導技能。"}]', '{"noun":"skill","adjective":"skilled, skillful"}', NULL, 2, 1870),
(1871, 'sleep', '/sliːp/', 'verb', '{"zh-TW":["睡覺"],"en":["to rest with eyes closed and mind unconscious"]}', NULL, 'lose sleep over / sleep on it', '[{"en":"Don''t lose sleep over this issue.","zh-TW":"不要因為這個問題而失眠。"},{"en":"Let me sleep on it and decide tomorrow.","zh-TW":"讓我考慮一晚，明天再決定。"}]', '{"verb":"sleep","noun":"sleep","adjective":"sleepy","adjective2":"sleepless"}', NULL, 2, 1871),
(1872, 'slight', '/slaɪt/', 'adjective', '{"zh-TW":["輕微的；些微的"],"en":["small in degree; not important"]}', NULL, 'slight increase / slight delay / slight difference', '[{"en":"There was a slight delay in the shipment.","zh-TW":"貨物有些微的延遲。"},{"en":"We noticed a slight improvement in performance.","zh-TW":"我們注意到效能有些微的改善。"}]', '{"adjective":"slight","adverb":"slightly"}', NULL, 2, 1872),
(1873, 'slow', '/sloʊ/', 'adjective', '{"zh-TW":["慢的；緩慢的"],"en":["not moving fast","taking a long time"]}', NULL, 'slow down / slow growth', '[{"en":"Economic growth has slowed down.","zh-TW":"經濟成長放緩了。"},{"en":"The approval process is very slow.","zh-TW":"審批流程非常緩慢。"}]', '{"adjective":"slow","verb":"slow","adverb":"slowly","noun":"slowdown"}', NULL, 1, 1873),
(1874, 'small', '/smɔːl/', 'adjective', '{"zh-TW":["小的"],"en":["not large in size or amount"]}', NULL, 'small business / small talk', '[{"en":"We support small businesses.","zh-TW":"我們支持小型企業。"},{"en":"Make small talk before the meeting starts.","zh-TW":"會議開始前閒聊一下。"}]', '{"adjective":"small","noun":"smallness"}', NULL, 2, 1874),
(1875, 'smart', '/smɑːrt/', 'adjective', '{"zh-TW":["聰明的；智能的"],"en":["intelligent","using advanced technology"]}', NULL, 'smart decision / smart phone', '[{"en":"That was a smart business decision.","zh-TW":"那是一個聰明的商業決策。"},{"en":"Smart technology improves efficiency.","zh-TW":"智能科技提高了效率。"}]', '{"adjective":"smart","adverb":"smartly","noun":"smartphone"}', NULL, 2, 1875),
(1876, 'smile', '/smaɪl/', 'verb', '{"zh-TW":["微笑"],"en":["to form a pleased expression with the mouth"]}', NULL, 'smile at / with a smile', '[{"en":"She greeted every customer with a smile.","zh-TW":"她面帶微笑地迎接每位顧客。"},{"en":"Service with a smile makes a difference.","zh-TW":"帶著微笑的服務會有不同。"}]', '{"verb":"smile","noun":"smile"}', NULL, 2, 1876),
(1877, 'snow', '/snoʊ/', 'noun', '{"zh-TW":["雪"],"en":["frozen water falling from the sky"]}', NULL, 'snowball effect / snowed under', '[{"en":"I am snowed under with work this week.","zh-TW":"我這週工作堆積如山。"},{"en":"The issue had a snowball effect.","zh-TW":"這個問題產生了滾雪球效應。"}]', '{"noun":"snow","adjective":"snowy","verb":"snow"}', NULL, 1, 1877),
(1878, 'soar', '/sɔːr/', 'verb', '{"zh-TW":["飆升；暴漲","翱翔"],"en":["to rise rapidly; to fly high"]}', NULL, 'soar to new heights / prices soar / profits soar', '[{"en":"Fuel prices soared by 30% this quarter.","zh-TW":"本季燃油價格飆升了30%。"},{"en":"The company''s stock price soared after the announcement.","zh-TW":"公告後公司股價飆升。"}]', '{"verb":"soar","adjective":"soaring"}', NULL, 1, 1878),
(1879, 'soft', '/sɒft/', 'adjective', '{"zh-TW":["軟的；柔和的"],"en":["not hard","gentle"]}', NULL, 'soft skills / software', '[{"en":"Soft skills are as important as technical skills.","zh-TW":"軟實力和技術能力一樣重要。"},{"en":"The soft launch went smoothly.","zh-TW":"軟性上市進行順利。"}]', '{"adjective":"soft","verb":"soften","noun":"software","adverb":"softly"}', NULL, 1, 1879),
(1880, 'software', '/ˈsɒftwɛr/', 'noun', '{"zh-TW":["軟體"],"en":["programs used by a computer"]}', NULL, 'software update / software engineer', '[{"en":"Install the latest software update.","zh-TW":"安裝最新的軟體更新。"},{"en":"She develops educational software.","zh-TW":"她開發教育軟體。"}]', NULL, NULL, 3, 1880),
(1881, 'sole', '/soʊl/', 'adjective', '{"zh-TW":["唯一的；獨有的"],"en":["one and only; exclusive"]}', NULL, 'sole purpose / sole responsibility / sole proprietor', '[{"en":"She is the sole owner of the company.","zh-TW":"她是公司的唯一所有人。"},{"en":"The sole purpose of the meeting was budget approval.","zh-TW":"會議的唯一目的是預算審批。"}]', '{"adjective":"sole","adverb":"solely"}', NULL, 1, 1881),
(1882, 'solicit', '/səˈlɪsɪt/', 'verb', '{"zh-TW":["徵求；請求"],"en":["to ask for something earnestly"]}', NULL, 'solicit feedback / solicit bids / solicit opinions', '[{"en":"The company solicited feedback from its customers.","zh-TW":"公司向客戶徵求回饋。"},{"en":"We solicited bids from multiple vendors.","zh-TW":"我們向多家供應商徵求報價。"}]', '{"noun":"solicitation","verb":"solicit"}', NULL, 3, 1882),
(1883, 'solidify', '/səˈlɪdɪfaɪ/', 'verb', '{"zh-TW":["鞏固；使堅固"],"en":["to make or become firm or strong"]}', NULL, 'solidify one''s position / solidify partnerships', '[{"en":"The merger solidified the company''s market position.","zh-TW":"合併鞏固了公司的市場地位。"},{"en":"We aim to solidify our partnerships in the region.","zh-TW":"我們旨在鞏固在該地區的合作夥伴關係。"}]', '{"noun":"solidarity","verb":"solidify","adjective":"solid"}', NULL, 3, 1883),
(1884, 'solve', '/sɑːlv/', 'verb', '{"zh-TW":["解決；解答"],"en":["to find an answer to a problem"]}', NULL, 'solve a problem / solve an issue / problem-solving', '[{"en":"We need to solve this issue before launch.","zh-TW":"我們需要在上線前解決這個問題。"},{"en":"The team solved the technical challenge quickly.","zh-TW":"團隊很快解決了技術挑戰。"}]', '{"noun":"solution","verb":"solve","adjective":"solvable, unsolved"}', NULL, 2, 1884),
(1885, 'somewhat', '/ˈsʌmwɑːt/', 'adverb', '{"zh-TW":["有點；稍微"],"en":["to some extent; a little"]}', NULL, 'somewhat different / somewhat surprising / somewhat difficult', '[{"en":"The results were somewhat disappointing.","zh-TW":"結果有點令人失望。"},{"en":"The process is somewhat more complex than expected.","zh-TW":"這個流程比預期的稍微複雜一些。"}]', '{"adverb":"somewhat"}', NULL, 3, 1885),
(1886, 'son', '/sʌn/', 'noun', '{"zh-TW":["兒子"],"en":["a male child"]}', NULL, 'only son / son-in-law', '[{"en":"His son joined the family business.","zh-TW":"他的兒子加入了家族企業。"},{"en":"My son-in-law works in accounting.","zh-TW":"我的女婿在會計部門工作。"}]', '{"noun":"son"}', NULL, 1, 1886),
(1887, 'soon', '/suːn/', 'adverb', '{"zh-TW":["很快；不久"],"en":["in a short time"]}', NULL, 'as soon as / sooner or later', '[{"en":"We will launch as soon as possible.","zh-TW":"我們會盡快推出。"},{"en":"Sooner or later, the truth will come out.","zh-TW":"遲早真相會水落石出。"}]', '{"adverb":"soon","adjective":"soon"}', NULL, 1, 1887),
(1888, 'sophisticated', '/səˈfɪstɪkeɪtɪd/', 'adjective', '{"zh-TW":["精密的；複雜的","世故的"],"en":["highly developed and complex","having refined taste"]}', NULL, 'sophisticated technology / sophisticated system / sophisticated approach', '[{"en":"The company uses sophisticated data analytics.","zh-TW":"公司使用精密的數據分析。"},{"en":"This requires a more sophisticated approach.","zh-TW":"這需要更精密的方法。"}]', '{"noun":"sophistication","adjective":"sophisticated"}', NULL, 5, 1888),
(1889, 'sophomore', '/ˈsɒfəmɔːr/', 'noun', '{"zh-TW":["大二學生"],"en":["a second-year student"]}', NULL, 'sophomore year / sophomore album', '[{"en":"She''s a sophomore in college.","zh-TW":"她是大二學生。"},{"en":"His sophomore year was the hardest.","zh-TW":"他的大二是最辛苦的。"}]', NULL, NULL, 3, 1889),
(1890, 'sorry', '/ˈsɒri/', 'adjective', '{"zh-TW":["抱歉的"],"en":["feeling regret or apology"]}', NULL, 'sorry for / sorry to hear', '[{"en":"I am sorry for the inconvenience.","zh-TW":"很抱歉造成不便。"},{"en":"Sorry to hear about the delay.","zh-TW":"很遺憾聽到延遲的消息。"}]', '{"adjective":"sorry"}', NULL, 2, 1890),
(1891, 'sound', '/saʊnd/', 'noun', '{"zh-TW":["聲音；聽起來"],"en":["something heard","to seem"]}', NULL, 'sound advice / sounds good', '[{"en":"That sounds like a good plan.","zh-TW":"聽起來是個好計畫。"},{"en":"He gave us sound financial advice.","zh-TW":"他給了我們可靠的財務建議。"}]', '{"noun":"sound","verb":"sound","adjective":"sound","adverb":"soundly"}', NULL, 2, 1891),
(1892, 'source', '/sɔːrs/', 'noun, verb', '{"zh-TW":["來源；出處","採購；尋找來源"],"en":["a place from which something comes","to obtain from a particular place"]}', NULL, 'reliable source / source of income / source materials', '[{"en":"Tourism is the main source of income for the region.","zh-TW":"旅遊業是該地區的主要收入來源。"},{"en":"We source our materials from local suppliers.","zh-TW":"我們從當地供應商採購材料。"}]', '{"noun":"source","verb":"source, outsource"}', NULL, 2, 1892),
(1893, 'space', '/speɪs/', 'noun', '{"zh-TW":["空間；太空"],"en":["an area available for use","the universe beyond Earth"]}', NULL, 'office space / co-working space', '[{"en":"We are looking for new office space.","zh-TW":"我們正在尋找新的辦公空間。"},{"en":"Co-working spaces are popular with startups.","zh-TW":"共同工作空間很受新創公司歡迎。"}]', '{"noun":"space","adjective":"spacious","verb":"space"}', NULL, 2, 1893),
(1894, 'span', '/spæn/', 'noun, verb', '{"zh-TW":["跨度；時間段","跨越"],"en":["the full extent of something","to extend across"]}', NULL, 'time span / attention span / span a period', '[{"en":"The project spans a period of three years.","zh-TW":"該專案跨越三年時間。"},{"en":"The average attention span is decreasing.","zh-TW":"平均注意力持續時間正在減少。"}]', '{"noun":"span","verb":"span"}', NULL, 1, 1894),
(1895, 'spare', '/sper/', 'adjective, verb', '{"zh-TW":["備用的；多餘的","騰出；省下"],"en":["extra; not being used","to make available"]}', NULL, 'spare time / spare parts / spare no effort', '[{"en":"Do you have any spare time this afternoon?","zh-TW":"你今天下午有空閒時間嗎？"},{"en":"We spare no effort in ensuring quality.","zh-TW":"我們不遺餘力地確保品質。"}]', '{"noun":"spare","verb":"spare","adjective":"spare"}', NULL, 2, 1895),
(1896, 'speak', '/spiːk/', 'verb', '{"zh-TW":["說話；發言"],"en":["to talk","to address an audience"]}', NULL, 'speak up / so to speak', '[{"en":"Please speak up if you disagree.","zh-TW":"如果不同意請大聲說出來。"},{"en":"She will speak at the conference.","zh-TW":"她將在會議上演講。"}]', '{"verb":"speak","noun":"speaker","noun2":"speech"}', NULL, 2, 1896),
(1897, 'specific', '/spɪˈsɪfɪk/', 'adjective', '{"zh-TW":["具體的；明確的","特定的"],"en":["clearly defined or identified","particular"]}', NULL, 'specific requirements / specific details / industry-specific', '[{"en":"Please provide specific examples.","zh-TW":"請提供具體的例子。"},{"en":"The instructions are very specific.","zh-TW":"指示非常明確。"}]', '{"noun":"specification, specifics","adjective":"specific","adverb":"specifically"}', NULL, 3, 1897),
