(1906, 'sport', '/spɔːrt/', 'verb, noun, adjective', '{"zh-TW":["【主要意義】體育運動；娛樂消遣","【次要意義-動詞】炫耀地穿戴；誇示","【次要意義-名詞】光明磊落的人；有運動精神的人"],"en":["[primary] athletic activity or game","[secondary - verb] to wear or display something proudly or noticeably","[secondary - noun] a person who accepts defeat or teasing cheerfully"]}', NULL, 'sport a new hairstyle / sport a badge / be a good sport', '[{"en":"She sported a brand new designer handbag at the meeting.","zh-TW":"她在會議上炫耀地提著一個全新的設計師手提包。"},{"en":"He was a good sport about losing the competition.","zh-TW":"他輸了比賽後表現得很有運動精神。"},{"en":"The new employee sported a confident smile on his first day.","zh-TW":"新員工在第一天上班時臉上掛著自信的微笑。"}]', '{"noun":"sports, sportsmanship","adjective":"sporting, sporty"}', '動詞用法 sport = 炫耀地展示，常出現在描述外貌或穿著的語境中，TOEIC 閱讀常見陷阱。', 2, 1906),
(1907, 'spot', '/spɑːt/', 'noun, verb', '{"zh-TW":["地點；位置","發現；注意到"],"en":["a particular place","to notice or identify"]}', NULL, 'on the spot / spot a trend / weak spot', '[{"en":"She spotted an error in the financial report.","zh-TW":"她發現了財務報告中的一個錯誤。"},{"en":"The manager made a decision on the spot.","zh-TW":"經理當場做出了決定。"}]', '{"noun":"spot","verb":"spot"}', NULL, 1, 1907),
