(1932, 'stimulate', '/ˈstɪmjuleɪt/', 'verb', '{"zh-TW":["刺激；激勵"],"en":["to encourage activity or development"]}', NULL, 'stimulate growth / stimulate the economy / stimulate demand', '[{"en":"The government introduced measures to stimulate the economy.","zh-TW":"政府推出了刺激經濟的措施。"},{"en":"Lower prices stimulate consumer demand.","zh-TW":"較低的價格刺激了消費者需求。"}]', '{"noun":"stimulation, stimulus","verb":"stimulate","adjective":"stimulating"}', NULL, 3, 1932),
(1933, 'stock', '/stɒk/', 'noun', '{"zh-TW":["存貨；股票","股票；庫存","儲備；進貨"],"en":["goods available for sale","shares in a company","shares in a company; goods kept for sale","to keep a supply of"]}', '{"root":{"text":"stock","meaning":"trunk/store (樹幹/儲存)"},"logic":"原指樹幹（根基），引申為儲存的貨物。"}', 'in stock / out of stock / stock market; stock market / in stock / out of stock / stock price', '[{"en":"Sorry, that item is out of stock.","zh-TW":"抱歉，那個商品缺貨了。"},{"en":"We need to restock the shelves.","zh-TW":"我們需要補貨上架。"},{"en":"The stock market rallied after the announcement.","zh-TW":"公告後股市反彈。"},{"en":"The item is currently out of stock.","zh-TW":"該商品目前缺貨。"}]', '{"verb":"stock","noun":"stockholder"}', NULL, 2, 1933),
(1934, 'stop', '/stɒp/', 'verb', '{"zh-TW":["停止"],"en":["to cease moving or doing"]}', NULL, 'stop by / non-stop', '[{"en":"Please stop by my office later.","zh-TW":"請待會過來我的辦公室一趟。"},{"en":"We worked non-stop to finish on time.","zh-TW":"我們不停地工作以準時完成。"}]', '{"verb":"stop","noun":"stop","noun2":"stoppage"}', NULL, 1, 1934),
(1935, 'storage', '/ˈstɔːrɪdʒ/', 'noun', '{"zh-TW":["儲存；儲存空間","儲存；倉儲"],"en":["the keeping of things for future use","the keeping of goods in a designated place"]}', NULL, 'cloud storage / storage space; data storage / storage capacity / cold storage', '[{"en":"I need more storage on my phone.","zh-TW":"我手機需要更多儲存空間。"},{"en":"Cloud storage is convenient.","zh-TW":"雲端儲存很方便。"},{"en":"Cloud storage has become essential for businesses.","zh-TW":"雲端儲存已成為企業的必需。"},{"en":"The warehouse has limited storage capacity.","zh-TW":"倉庫的儲存容量有限。"}]', '{"verb":"store","noun":"storage, store"}', NULL, 3, 1935),
