(1938, 'story', '/ˈstɔːri/', 'noun', '{"zh-TW":["故事；樓層"],"en":["a narrative","a level of a building"]}', NULL, 'success story / cover story', '[{"en":"Our company has a great success story.","zh-TW":"我們公司有一個精彩的成功故事。"},{"en":"The office building is ten stories tall.","zh-TW":"辦公大樓有十層樓高。"}]', '{"noun":"story","noun2":"storyline"}', NULL, 2, 1938),
(1939, 'straightforward', '/ˌstreɪtˈfɔːrwərd/', 'adjective', '{"zh-TW":["直截了當的；簡單的"],"en":["easy to understand; uncomplicated"]}', NULL, 'straightforward process / straightforward answer / fairly straightforward', '[{"en":"The application process is straightforward.","zh-TW":"申請流程很簡單。"},{"en":"He gave a straightforward answer to the question.","zh-TW":"他對問題給出了直截了當的回答。"}]', '{"adjective":"straightforward","adverb":"straightforwardly"}', NULL, 5, 1939),
(1940, 'strategy', '/ˈstrætədʒi/', 'noun', '{"zh-TW":["策略","策略；戰略"],"en":["a plan of action to achieve a long-term goal","a plan designed to achieve a long-term goal"]}', '{"root":{"text":"strat","meaning":"army (軍隊)"},"suffix":{"text":"-egy","meaning":"leading (引領)"},"logic":"引領軍隊的計畫，即「策略」。"}', 'marketing strategy / business strategy / develop a strategy; business strategy / marketing strategy / develop a strategy', '[{"en":"We need a new strategy to increase sales.","zh-TW":"我們需要新策略來增加銷售。"},{"en":"The company developed a long-term growth strategy.","zh-TW":"公司制定了長期成長策略。"},{"en":"The company revised its marketing strategy.","zh-TW":"公司修改了行銷策略。"},{"en":"We need a clear strategy for expansion.","zh-TW":"我們需要明確的擴展策略。"}]', '{"adjective":"strategic","adverb":"strategically","noun2":"strategist","noun":"strategy, strategist"}', NULL, 3, 1940),
(1941, 'streaming', '/ˈstriːmɪŋ/', 'noun', '{"zh-TW":["串流"],"en":["transmitting data continuously over the internet"]}', NULL, 'video streaming / streaming service', '[{"en":"Streaming has replaced traditional TV.","zh-TW":"串流取代了傳統電視。"},{"en":"Which streaming service do you subscribe to?","zh-TW":"你訂閱了哪個串流服務？"}]', '{"verb":"stream"}', NULL, 3, 1941),
(1942, 'streamline', '/ˈstriːmlaɪn/', 'verb', '{"zh-TW":["精簡；使流暢"],"en":["to make a process more efficient"]}', NULL, 'streamline operations / streamline processes / streamline workflow', '[{"en":"The company streamlined its production process.","zh-TW":"公司精簡了生產流程。"},{"en":"New technology helps streamline daily operations.","zh-TW":"新技術有助於精簡日常營運。"}]', '{"verb":"streamline","adjective":"streamlined"}', NULL, 4, 1942),
(1943, 'streamlined', '/ˈstriːmlaɪnd/', 'adjective', '{"zh-TW":["精簡的；流線型的"],"en":["designed for efficiency; having smooth lines"]}', NULL, 'streamlined process / streamlined design / streamlined operations', '[{"en":"The new streamlined process saves two hours per day.","zh-TW":"新的精簡流程每天節省兩小時。"},{"en":"We implemented a streamlined approval system.","zh-TW":"我們實施了精簡的審批系統。"}]', '{"adjective":"streamlined","verb":"streamline"}', NULL, 4, 1943),
(1944, 'street', '/striːt/', 'noun', '{"zh-TW":["街道"],"en":["a public road in a city or town"]}', NULL, 'Wall Street / main street', '[{"en":"Wall Street reacted positively to the news.","zh-TW":"華爾街對這個消息反應正面。"},{"en":"The store is on the main street.","zh-TW":"商店在主要街道上。"}]', '{"noun":"street"}', NULL, 2, 1944),
(1945, 'strengthen', '/ˈstreŋθn/', 'verb', '{"zh-TW":["加強；增強"],"en":["to make or become stronger"]}', NULL, 'strengthen ties / strengthen the position / strengthen regulations', '[{"en":"The partnership will strengthen our market position.","zh-TW":"合作將加強我們的市場地位。"},{"en":"The government strengthened environmental regulations.","zh-TW":"政府加強了環境法規。"}]', '{"noun":"strength","verb":"strengthen","adjective":"strong"}', NULL, 4, 1945),
(1946, 'stress', '/stres/', 'noun, verb', '{"zh-TW":["壓力；緊張","強調"],"en":["mental or emotional pressure","to emphasize"]}', NULL, 'under stress / stress the importance / stress management', '[{"en":"She stressed the importance of meeting deadlines.","zh-TW":"她強調了遵守截止日期的重要性。"},{"en":"Many employees suffer from workplace stress.","zh-TW":"許多員工受到工作壓力的影響。"}]', '{"noun":"stress","verb":"stress","adjective":"stressful, stressed"}', NULL, 2, 1946),
(1947, 'strict', '/strɪkt/', 'adjective', '{"zh-TW":["嚴格的；嚴謹的"],"en":["demanding that rules are obeyed"]}', NULL, 'strict regulations / strict deadline / strict compliance', '[{"en":"The company has strict policies on data privacy.","zh-TW":"公司對資料隱私有嚴格的政策。"},{"en":"Strict compliance with safety standards is required.","zh-TW":"必須嚴格遵守安全標準。"}]', '{"adjective":"strict","adverb":"strictly","noun":"strictness"}', NULL, 2, 1947),
(1948, 'strike', '/straɪk/', 'noun, verb', '{"zh-TW":["罷工；打擊","罷工；襲擊"],"en":["a refusal to work as a protest","to hit or attack"]}', NULL, 'go on strike / strike a deal / strike a balance', '[{"en":"Workers went on strike for higher wages.","zh-TW":"工人為爭取更高薪資而罷工。"},{"en":"We need to strike a balance between cost and quality.","zh-TW":"我們需要在成本和品質之間取得平衡。"}]', '{"noun":"strike, striker","verb":"strike"}', NULL, 2, 1948),
(1949, 'strive', '/straɪv/', 'verb', '{"zh-TW":["努力；奮鬥"],"en":["to make great efforts to achieve something"]}', NULL, 'strive for excellence / strive to achieve / strive to improve', '[{"en":"We strive for excellence in customer service.","zh-TW":"我們在客戶服務方面追求卓越。"},{"en":"The team strives to meet all deadlines.","zh-TW":"團隊努力在所有截止日前完成工作。"}]', '{"verb":"strive"}', NULL, 2, 1949);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1950, 'strong', '/strɒŋ/', 'adjective', '{"zh-TW":["強壯的；強大的"],"en":["having great power","solid and difficult to break"]}', NULL, 'strong demand / strong leadership', '[{"en":"There is strong demand for this product.","zh-TW":"這個產品需求強勁。"},{"en":"Strong leadership guided the company through the crisis.","zh-TW":"強有力的領導帶領公司度過了危機。"}]', '{"adjective":"strong","adverb":"strongly","noun":"strength","verb":"strengthen"}', NULL, 2, 1950),
(1951, 'structure', '/ˈstrʌktʃər/', 'noun, verb', '{"zh-TW":["結構；組織","構建；組織"],"en":["the way something is organized","to arrange in a systematic way"]}', NULL, 'organizational structure / cost structure / well-structured', '[{"en":"The company restructured its organizational structure.","zh-TW":"公司重組了其組織結構。"},{"en":"The report is well-structured and easy to follow.","zh-TW":"報告結構完善，易於理解。"}]', '{"noun":"structure, restructuring","verb":"structure, restructure","adjective":"structural"}', NULL, 3, 1951),
(1952, 'stubborn', '/ˈstʌbərn/', 'adjective', '{"zh-TW":["固執的"],"en":["refusing to change one''s mind"]}', '{"root":{"text":"stub","meaning":"stump (樹樁)"},"logic":"如同樹樁般不動搖的，即「固執的」。"}', 'stubborn refusal / stubborn as a mule', '[{"en":"He is too stubborn to ask for help.","zh-TW":"他太固執不肯求助。"},{"en":"Her stubborn refusal caused problems.","zh-TW":"她固執的拒絕造成了問題。"}]', '{"noun":"stubbornness","adverb":"stubbornly"}', NULL, 3, 1952),
(1953, 'student', '/ˈstjuːdənt/', 'noun', '{"zh-TW":["學生"],"en":["a person who is studying"]}', NULL, 'student loan / exchange student', '[{"en":"Student loans are a heavy burden.","zh-TW":"學生貸款是沉重的負擔。"},{"en":"We hire exchange students as interns.","zh-TW":"我們聘請交換學生當實習生。"}]', '{"noun":"student","noun2":"study","verb":"study"}', NULL, 3, 1953),
(1954, 'studio', '/ˈstjuːdioʊ/', 'noun', '{"zh-TW":["工作室；錄音室"],"en":["a room where an artist or musician works"]}', '{"root":{"text":"studi","meaning":"study/devote (研究/投入)"},"suffix":{"text":"-o","meaning":"place (場所)"},"logic":"投入研究創作的場所，即「工作室」。"}', 'art studio / recording studio / studio apartment', '[{"en":"The photographer works in her studio.","zh-TW":"攝影師在她的工作室工作。"},{"en":"The band recorded the album in a professional studio.","zh-TW":"樂團在專業錄音室錄製了這張專輯。"}]', NULL, NULL, 2, 1954),
(1955, 'study', '/ˈstʌdi/', 'verb', '{"zh-TW":["學習；研究"],"en":["to learn about a subject","to examine carefully"]}', NULL, 'case study / feasibility study', '[{"en":"We conducted a feasibility study.","zh-TW":"我們進行了可行性研究。"},{"en":"This case study shows best practices.","zh-TW":"這個案例研究展示了最佳實踐。"}]', '{"verb":"study","noun":"study","noun2":"student"}', NULL, 2, 1955),
(1956, 'subcontract', '/ˌsʌbkənˈtrækt/', 'verb, noun', '{"zh-TW":["分包；轉包","分包合約"],"en":["to hire another company to do part of the work"]}', NULL, 'subcontract work / subcontract to / subcontractor', '[{"en":"The firm subcontracted the IT work to a specialist.","zh-TW":"公司將IT工作分包給專業人員。"},{"en":"We use subcontractors for maintenance services.","zh-TW":"我們使用分包商提供維護服務。"}]', '{"noun":"subcontract, subcontractor","verb":"subcontract"}', NULL, 4, 1956),
(1957, 'subject', '/ˈsʌbdʒɪkt/', 'noun, adjective, verb', '{"zh-TW":["主題；科目","受...支配的","使遭受"],"en":["a topic; a branch of study","dependent on","to cause to experience"]}', NULL, 'subject to / on the subject of / subject matter', '[{"en":"The plan is subject to board approval.","zh-TW":"該計畫需經董事會批准。"},{"en":"Let''s not change the subject.","zh-TW":"我們不要改變話題。"}]', '{"noun":"subject","verb":"subject","adjective":"subject, subjective"}', NULL, 3, 1957),
(1958, 'submit', '/səbˈmɪt/', 'verb', '{"zh-TW":["提交；呈交","服從"],"en":["to present for consideration","to yield to authority"]}', '{"prefix":{"text":"sub-","meaning":"在...之下"},"root":{"text":"mit","meaning":"send (發送)"}}', 'submit a report / submit an application / submit a proposal', '[{"en":"Please submit your application by Friday.","zh-TW":"請在週五前提交您的申請。"},{"en":"All expenses must be submitted for approval.","zh-TW":"所有費用都必須提交審批。"}]', '{"noun":"submission","verb":"submit"}', NULL, 2, 1958),
(1959, 'subordinate', '/səˈbɔːrdɪnət/', 'noun, adjective', '{"zh-TW":["下屬；部屬","次要的；從屬的"],"en":["a person under the authority of another","lower in rank"]}', NULL, 'subordinate to / direct subordinate', '[{"en":"Managers should support their subordinates.","zh-TW":"經理應該支持他們的下屬。"},{"en":"Personal interests are subordinate to company goals.","zh-TW":"個人利益從屬於公司目標。"}]', '{"noun":"subordinate, subordination","adjective":"subordinate","verb":"subordinate"}', NULL, 4, 1959),
(1960, 'subscribe', '/səbˈskraɪb/', 'verb', '{"zh-TW":["訂閱；認購","同意"],"en":["to pay regularly for a service","to agree with an idea"]}', NULL, 'subscribe to / subscription service / subscribe to a newsletter', '[{"en":"Over 10,000 users subscribe to our newsletter.","zh-TW":"超過一萬名用戶訂閱我們的電子報。"},{"en":"I don''t subscribe to that theory.","zh-TW":"我不認同那個理論。"}]', '{"noun":"subscription, subscriber","verb":"subscribe"}', NULL, 3, 1960),
(1961, 'subsequent', '/ˈsʌbsɪkwənt/', 'adjective', '{"zh-TW":["隨後的；後續的"],"en":["coming after something in time"]}', NULL, 'subsequent to / subsequent events / in subsequent years', '[{"en":"Subsequent meetings will address remaining issues.","zh-TW":"後續會議將處理剩餘問題。"},{"en":"Sales improved in subsequent quarters.","zh-TW":"銷售額在接下來的幾季有所改善。"}]', '{"adjective":"subsequent","adverb":"subsequently"}', NULL, 4, 1961),
(1962, 'subsidiary', '/səbˈsɪdieri/', 'noun, adjective', '{"zh-TW":["子公司","附屬的；次要的"],"en":["a company controlled by another company","less important"]}', NULL, 'wholly-owned subsidiary / subsidiary company', '[{"en":"The company has subsidiaries in 20 countries.","zh-TW":"該公司在20個國家設有子公司。"},{"en":"This is a wholly-owned subsidiary of the group.","zh-TW":"這是集團的全資子公司。"}]', '{"noun":"subsidiary"}', NULL, 4, 1962),
(1963, 'substance', '/ˈsʌbstəns/', 'noun', '{"zh-TW":["物質；實質","要旨"],"en":["a type of matter","the real content or meaning"]}', NULL, 'chemical substance / in substance / substance abuse', '[{"en":"The report lacks substance.","zh-TW":"這份報告缺乏實質內容。"},{"en":"Hazardous substances must be handled carefully.","zh-TW":"危險物質必須小心處理。"}]', '{"noun":"substance","adjective":"substantial, substantive"}', NULL, 3, 1963),
(1964, 'substantial', '/səbˈstænʃl/', 'adjective', '{"zh-TW":["大量的；可觀的","實質的"],"en":["of considerable importance or size"]}', NULL, 'substantial amount / substantial improvement / substantial evidence', '[{"en":"We made a substantial investment in technology.","zh-TW":"我們在技術方面進行了大量投資。"},{"en":"There has been substantial improvement in quality.","zh-TW":"品質有了顯著的改善。"}]', '{"noun":"substance","adjective":"substantial","adverb":"substantially"}', NULL, 4, 1964),
(1965, 'substitute', '/ˈsʌbstɪtuːt/', 'noun, verb', '{"zh-TW":["替代品；代替者","替代；取代"],"en":["a person or thing acting in place of another","to use instead of"]}', NULL, 'substitute for / substitute teacher / no substitute for', '[{"en":"There is no substitute for hard work.","zh-TW":"勤奮是無可替代的。"},{"en":"You can substitute olive oil for butter.","zh-TW":"你可以用橄欖油代替奶油。"}]', '{"noun":"substitute, substitution","verb":"substitute"}', NULL, 4, 1965),
(1966, 'subtle', '/ˈsʌtl/', 'adjective', '{"zh-TW":["微妙的；細微的"],"en":["not immediately obvious; delicate"]}', NULL, 'subtle difference / subtle change / subtle hint', '[{"en":"There is a subtle difference between the two products.","zh-TW":"這兩款產品之間有微妙的差異。"},{"en":"She made a subtle hint about the promotion.","zh-TW":"她暗示了關於升遷的事。"}]', '{"noun":"subtlety","adjective":"subtle","adverb":"subtly"}', NULL, 2, 1966),
(1967, 'succeed', '/səkˈsiːd/', 'verb', '{"zh-TW":["成功；繼任"],"en":["to achieve a goal; to come after"]}', NULL, 'succeed in / succeed as / succeed someone', '[{"en":"The company succeeded in entering the Asian market.","zh-TW":"公司成功進入了亞洲市場。"},{"en":"She succeeded him as CEO.","zh-TW":"她接替他擔任執行長。"}]', '{"noun":"success, succession, successor","verb":"succeed","adjective":"successful, successive"}', NULL, 3, 1967),
(1968, 'sufficient', '/səˈfɪʃnt/', 'adjective', '{"zh-TW":["足夠的","足夠的；充分的"],"en":["enough to meet the needs"]}', '{"prefix":{"text":"suf-","meaning":"under/up (從下)"},"root":{"text":"fic","meaning":"make/do (做)"},"suffix":{"text":"-ient","meaning":"being (…的)"},"logic":"做到位的，即「足夠的」。"}', 'sufficient evidence / sufficient time / self-sufficient; sufficient funds / sufficient evidence / self-sufficient', '[{"en":"Do we have sufficient time to finish?","zh-TW":"我們有足夠的時間完成嗎？"},{"en":"The evidence is not sufficient to prove guilt.","zh-TW":"證據不足以證明有罪。"},{"en":"We have sufficient funds to complete the project.","zh-TW":"我們有足夠的資金完成這個專案。"},{"en":"The evidence is not sufficient to prove the claim.","zh-TW":"證據不足以證明該主張。"}]', '{"noun":"sufficiency","adverb":"sufficiently","adjective":"sufficient, insufficient"}', NULL, 4, 1968),
(1969, 'suggest', '/səˈdʒest/', 'verb', '{"zh-TW":["建議；暗示"],"en":["to put forward an idea; to indicate"]}', NULL, 'suggest that / strongly suggest / suggest an alternative', '[{"en":"I suggest we postpone the meeting.","zh-TW":"我建議我們延後會議。"},{"en":"The data suggests a positive trend.","zh-TW":"數據暗示了一個正面的趨勢。"}]', '{"noun":"suggestion","verb":"suggest","adjective":"suggestive"}', NULL, 3, 1969),
(1970, 'suit', '/suːt/', 'noun, verb', '{"zh-TW":["西裝；訴訟","適合"],"en":["a set of formal clothes; a legal action","to be convenient or acceptable for"]}', NULL, 'suit someone / business suit / lawsuit / well-suited', '[{"en":"The schedule suits everyone involved.","zh-TW":"這個時程安排適合所有相關人員。"},{"en":"She is well-suited for the leadership role.","zh-TW":"她非常適合這個領導角色。"}]', '{"noun":"suit, suitability","verb":"suit","adjective":"suitable, unsuitable"}', NULL, 1, 1970),
(1971, 'summarize', '/ˈsʌməraɪz/', 'verb', '{"zh-TW":["總結；概述"],"en":["to give a brief statement of the main points"]}', NULL, 'summarize the findings / to summarize / briefly summarize', '[{"en":"Please summarize the key findings of the report.","zh-TW":"請總結報告的主要發現。"},{"en":"To summarize, we need to reduce costs by 15%.","zh-TW":"總結來說，我們需要降低15%的成本。"}]', '{"noun":"summary","verb":"summarize"}', NULL, 3, 1971),
(1972, 'summit', '/ˈsʌmɪt/', 'noun', '{"zh-TW":["高峰會；峰會","頂點"],"en":["a meeting between heads of government","the highest point"]}', NULL, 'economic summit / summit meeting / reach the summit', '[{"en":"Leaders gathered for the G20 summit.","zh-TW":"領袖們齊聚G20高峰會。"},{"en":"The summit addressed climate change issues.","zh-TW":"峰會討論了氣候變遷議題。"}]', '{"noun":"summit"}', NULL, 2, 1972),
(1973, 'supervise', '/ˈsuːpərvaɪz/', 'verb', '{"zh-TW":["監督；管理"],"en":["to oversee the work of others"]}', NULL, 'supervise employees / supervise a project / closely supervised', '[{"en":"She supervises a team of 15 engineers.","zh-TW":"她管理一個15人的工程師團隊。"},{"en":"The construction work is closely supervised.","zh-TW":"施工工程受到密切監督。"}]', '{"noun":"supervision, supervisor","verb":"supervise","adjective":"supervisory"}', NULL, 3, 1973),
(1974, 'supplement', '/ˈsʌplɪmənt/', 'noun, verb', '{"zh-TW":["補充；補充物","補充"],"en":["something added to complete","to add to something"]}', NULL, 'supplement income / dietary supplement / supplement with', '[{"en":"Many freelancers supplement their income with part-time work.","zh-TW":"許多自由工作者用兼職來補充收入。"},{"en":"The report is supplemented with charts.","zh-TW":"報告附有圖表作為補充。"}]', '{"noun":"supplement","verb":"supplement","adjective":"supplementary"}', NULL, 4, 1974),
(1975, 'supply', '/səˈplaɪ/', 'noun, verb', '{"zh-TW":["供應；供給","供應；提供"],"en":["an amount available for use","to provide what is needed"]}', NULL, 'supply and demand / supply chain / supply shortage', '[{"en":"The supply chain was disrupted by the pandemic.","zh-TW":"供應鏈受到疫情的影響而中斷。"},{"en":"The company supplies parts to major automakers.","zh-TW":"這家公司為主要汽車製造商供應零件。"}]', '{"noun":"supply, supplier","verb":"supply"}', NULL, 2, 1975),
(1976, 'support', '/səˈpɔːrt/', 'noun, verb', '{"zh-TW":["支持；支援","支持；贊助"],"en":["help or encouragement","to give assistance to"]}', NULL, 'customer support / technical support / support a proposal', '[{"en":"The proposal received strong support from management.","zh-TW":"該提案獲得了管理層的大力支持。"},{"en":"We provide 24/7 customer support.","zh-TW":"我們提供全天候客戶支援。"}]', '{"noun":"support, supporter","verb":"support","adjective":"supportive"}', NULL, 3, 1976),
(1977, 'suppose', '/səˈpoʊz/', 'verb', '{"zh-TW":["假設；認為"],"en":["to assume; to believe"]}', NULL, 'be supposed to / I suppose / suppose that', '[{"en":"You are supposed to submit the form by today.","zh-TW":"你應該在今天之前提交表格。"},{"en":"I suppose we could try a different approach.","zh-TW":"我想我們可以嘗試不同的方法。"}]', '{"noun":"supposition","verb":"suppose","adjective":"supposed"}', NULL, 3, 1977),
(1978, 'suppress', '/səˈpres/', 'verb', '{"zh-TW":["壓制；抑制"],"en":["to prevent from being expressed or known"]}', NULL, 'suppress information / suppress competition / suppress dissent', '[{"en":"The company tried to suppress negative reviews.","zh-TW":"公司試圖壓制負面評論。"},{"en":"Rising interest rates suppressed consumer spending.","zh-TW":"利率上升抑制了消費支出。"}]', '{"noun":"suppression","verb":"suppress"}', NULL, 3, 1978),
(1979, 'sure', '/ʃʊr/', 'adjective', '{"zh-TW":["確定的；當然"],"en":["certain; confident"]}', NULL, 'make sure / for sure', '[{"en":"Make sure you save the file.","zh-TW":"確保你儲存了檔案。"},{"en":"We will finish on time for sure.","zh-TW":"我們肯定會準時完成。"}]', '{"adjective":"sure","adverb":"surely"}', NULL, 1, 1979),
(1980, 'surge', '/sɜːrdʒ/', 'noun, verb', '{"zh-TW":["激增；猛漲","急增；湧現"],"en":["a sudden large increase","to increase suddenly"]}', NULL, 'surge in demand / price surge / power surge', '[{"en":"There was a surge in online orders during the holiday.","zh-TW":"假期期間線上訂單激增。"},{"en":"Oil prices surged after the announcement.","zh-TW":"公告後油價猛漲。"}]', '{"noun":"surge","verb":"surge"}', NULL, 2, 1980),
(1981, 'surpass', '/sərˈpæs/', 'verb', '{"zh-TW":["超越；勝過"],"en":["to exceed or be better than"]}', NULL, 'surpass expectations / surpass a record / surpass competitors', '[{"en":"Sales surpassed expectations by 20%.","zh-TW":"銷售額超出預期20%。"},{"en":"The company surpassed its competitors in revenue.","zh-TW":"該公司在營收上超越了競爭對手。"}]', '{"verb":"surpass"}', NULL, 3, 1981),
(1982, 'surplus', '/ˈsɜːrpləs/', 'noun, adjective', '{"zh-TW":["剩餘；盈餘","多餘的"],"en":["an amount left over","more than what is needed"]}', NULL, 'budget surplus / trade surplus / surplus inventory', '[{"en":"The government reported a budget surplus.","zh-TW":"政府報告了預算盈餘。"},{"en":"Surplus inventory was sold at a discount.","zh-TW":"多餘的庫存以折扣價出售。"}]', '{"noun":"surplus","adjective":"surplus"}', NULL, 3, 1982),
(1983, 'surprise', '/sərˈpraɪz/', 'noun', '{"zh-TW":["驚喜；意外"],"en":["an unexpected event"]}', NULL, 'come as a surprise / surprise visit', '[{"en":"The announcement came as no surprise.","zh-TW":"這個公告並不令人意外。"},{"en":"The CEO made a surprise visit.","zh-TW":"執行長進行了突擊訪視。"}]', '{"noun":"surprise","verb":"surprise","adjective":"surprising","adverb":"surprisingly"}', NULL, 3, 1983),
(1984, 'surveillance', '/sɜːrˈveɪləns/', 'noun', '{"zh-TW":["監控；監視"],"en":["close observation of a person or place"]}', NULL, 'under surveillance / surveillance camera / surveillance system', '[{"en":"The building is equipped with surveillance cameras.","zh-TW":"這棟建築配有監視攝影機。"},{"en":"The suspect was placed under surveillance.","zh-TW":"嫌疑人被置於監控之下。"}]', '{"noun":"surveillance","verb":"surveil"}', NULL, 4, 1984),
(1985, 'survey', '/ˈsɜːrveɪ/', 'noun, verb', '{"zh-TW":["調查；問卷","進行調查"],"en":["a study of opinions or conditions","to investigate"]}', NULL, 'conduct a survey / customer survey / survey results', '[{"en":"We conducted a customer satisfaction survey.","zh-TW":"我們進行了客戶滿意度調查。"},{"en":"The survey revealed key market trends.","zh-TW":"調查揭示了主要的市場趨勢。"}]', '{"noun":"survey, surveyor","verb":"survey"}', NULL, 2, 1985),
(1986, 'survive', '/sərˈvaɪv/', 'verb', '{"zh-TW":["存活；度過","倖存"],"en":["to continue to live or exist"]}', NULL, 'survive a crisis / survival rate / survive competition', '[{"en":"Few small businesses survive beyond five years.","zh-TW":"很少有小企業能存活超過五年。"},{"en":"The company survived the economic downturn.","zh-TW":"這家公司撐過了經濟衰退。"}]', '{"noun":"survival, survivor","verb":"survive"}', NULL, 3, 1986),
(1987, 'susceptible', '/səˈseptəbl/', 'adjective', '{"zh-TW":["易受影響的；敏感的"],"en":["likely to be affected by something"]}', NULL, 'susceptible to / highly susceptible / susceptible to change', '[{"en":"The market is susceptible to sudden changes.","zh-TW":"市場容易受到突然變化的影響。"},{"en":"Older systems are more susceptible to cyber attacks.","zh-TW":"較舊的系統更容易受到網路攻擊。"}]', '{"noun":"susceptibility","adjective":"susceptible"}', NULL, 4, 1987),
(1988, 'suspect', '/səˈspekt/', 'verb, noun', '{"zh-TW":["懷疑；猜想","嫌疑犯"],"en":["to believe something is likely","a person thought to be guilty"]}', NULL, 'suspect fraud / suspect that / prime suspect', '[{"en":"Auditors suspect financial irregularities.","zh-TW":"審計員懷疑有財務違規行為。"},{"en":"I suspect the delay is due to supply issues.","zh-TW":"我懷疑延遲是由於供應問題。"}]', '{"noun":"suspect, suspicion","verb":"suspect","adjective":"suspicious, suspected"}', NULL, 3, 1988),
(1989, 'suspend', '/səˈspend/', 'verb', '{"zh-TW":["暫停；中止","懸掛"],"en":["to temporarily stop","to hang from above"]}', NULL, 'suspend operations / suspend trading / suspend an employee', '[{"en":"The company suspended trading of its shares.","zh-TW":"公司暫停了股票交易。"},{"en":"Operations were suspended due to safety concerns.","zh-TW":"因安全顧慮，營運已暫停。"}]', '{"noun":"suspension","verb":"suspend"}', NULL, 3, 1989),
(1990, 'sustain', '/səˈsteɪn/', 'verb', '{"zh-TW":["維持；承受","維持；持續","承受"],"en":["to maintain at a certain level","to suffer or experience","to maintain over time","to suffer or endure"]}', '{"prefix":{"text":"sus-","meaning":"under (從下)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"從下方支撐持住，即「維持」。"}', 'sustain growth / sustain an injury / sustainable development; sustain growth / sustain losses / sustainable development', '[{"en":"The economy cannot sustain this level of spending.","zh-TW":"經濟無法維持這種支出水平。"},{"en":"He sustained minor injuries in the accident.","zh-TW":"他在事故中受了輕傷。"},{"en":"The business needs to sustain profitability.","zh-TW":"企業需要維持盈利能力。"},{"en":"The company sustained heavy losses last year.","zh-TW":"公司去年蒙受了重大損失。"}]', '{"adjective":"sustainable","noun":"sustainability","verb":"sustain"}', NULL, 3, 1990),
(1991, 'sweet', '/swiːt/', 'adjective', '{"zh-TW":["甜的；親切的"],"en":["having the taste of sugar","kind and pleasant"]}', NULL, 'sweet spot / sweet deal', '[{"en":"We found the sweet spot for pricing.","zh-TW":"我們找到了定價的最佳點。"},{"en":"That is a sweet deal for both parties.","zh-TW":"對雙方來說都是很棒的交易。"}]', '{"adjective":"sweet","noun":"sweetness","adverb":"sweetly","verb":"sweeten"}', NULL, 2, 1991),
(1992, 'switch', '/swɪtʃ/', 'noun, verb', '{"zh-TW":["轉換；開關","切換；轉變"],"en":["a change; a device for making connections","to change from one thing to another"]}', NULL, 'switch to / make the switch / switch providers', '[{"en":"Many companies switched to remote work.","zh-TW":"許多公司轉換為遠端工作。"},{"en":"Customers can switch providers without penalty.","zh-TW":"客戶可以無需罰款更換供應商。"}]', '{"noun":"switch","verb":"switch"}', NULL, 2, 1992),
(1993, 'syllabus', '/ˈsɪləbəs/', 'noun', '{"zh-TW":["課程大綱","教學大綱"],"en":["an outline of subjects in a course","a document showing what will be taught in a course"]}', NULL, 'course syllabus / follow the syllabus; course syllabus / on the syllabus', '[{"en":"The training syllabus is updated annually.","zh-TW":"培訓大綱每年更新。"},{"en":"Please review the syllabus before the course begins.","zh-TW":"請在課程開始前閱讀課程大綱。"},{"en":"Check the syllabus for due dates.","zh-TW":"查看教學大綱上的截止日期。"},{"en":"The syllabus outlines all assignments.","zh-TW":"教學大綱列出了所有作業。"}]', '{"noun":"syllabus"}', NULL, 3, 1993),
(1994, 'symbol', '/ˈsɪmbl/', 'noun', '{"zh-TW":["符號；象徵"],"en":["something that represents something else"]}', NULL, 'symbol of / stock symbol / status symbol', '[{"en":"The logo is a symbol of quality and trust.","zh-TW":"這個標誌是品質和信任的象徵。"},{"en":"Check the stock symbol before placing an order.","zh-TW":"下單前請確認股票代碼。"}]', '{"noun":"symbol, symbolism","verb":"symbolize","adjective":"symbolic"}', NULL, 2, 1994),
(1995, 'sympathetic', '/ˌsɪmpəˈθetɪk/', 'adjective', '{"zh-TW":["同情的；有同感的"],"en":["feeling or showing concern for someone''s misfortune"]}', '{"prefix":{"text":"sym-","meaning":"together (一起)"},"root":{"text":"path","meaning":"feeling (感受)"},"suffix":{"text":"-etic","meaning":"relating to (相關的)"},"logic":"一起感受的，即「同情的」。"}', 'sympathetic to / sympathetic ear', '[{"en":"She was sympathetic to his problems.","zh-TW":"她對他的問題表示同情。"},{"en":"He found a sympathetic listener in his friend.","zh-TW":"他在朋友那裡找到了知心的傾聽者。"}]', '{"noun":"sympathy","verb":"sympathize"}', NULL, 4, 1995),
(1996, 'sympathy', '/ˈsɪmpəθi/', 'noun', '{"zh-TW":["同情；同感"],"en":["feelings of pity and sorrow for someone"]}', NULL, 'express sympathy / in sympathy with / earn sympathy', '[{"en":"We express our deepest sympathy for your loss.","zh-TW":"我們對您的損失表示最深切的同情。"},{"en":"Workers went on strike in sympathy with the fired employees.","zh-TW":"工人們為聲援被解雇的員工而罷工。"}]', '{"noun":"sympathy","adjective":"sympathetic","verb":"sympathize"}', NULL, 3, 1996),
(1997, 'symphony', '/ˈsɪmfəni/', 'noun', '{"zh-TW":["交響曲"],"en":["a long piece of music for a full orchestra"]}', '{"prefix":{"text":"sym-","meaning":"together (一起)"},"root":{"text":"phon","meaning":"sound (聲音)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"聲音在一起和諧，即「交響曲」。"}', 'symphony orchestra / compose a symphony', '[{"en":"Beethoven''s Ninth Symphony is world-famous.","zh-TW":"貝多芬第九號交響曲舉世聞名。"},{"en":"We attended a symphony concert last night.","zh-TW":"我們昨晚參加了一場交響音樂會。"}]', '{"adjective":"symphonic"}', NULL, 3, 1997),
(1998, 'syndicate', '/ˈsɪndɪkɪt/', 'noun', '{"zh-TW":["辛迪加；聯合組織"],"en":["a group of individuals or organizations combined for a purpose"]}', NULL, 'banking syndicate / loan syndicate', '[{"en":"A banking syndicate financed the project.","zh-TW":"一個銀行聯合組織為專案提供了融資。"},{"en":"The loan was arranged through a syndicate.","zh-TW":"貸款透過聯貸組織安排。"}]', '{"noun":"syndicate","verb":"syndicate","noun2":"syndication"}', NULL, 3, 1998),
(1999, 'synthetic', '/sɪnˈθetɪk/', 'adjective', '{"zh-TW":["合成的；人造的"],"en":["made by chemical synthesis; not natural"]}', NULL, 'synthetic materials / synthetic fibers / synthetic data', '[{"en":"The jacket is made of synthetic fibers.","zh-TW":"這件夾克是用合成纖維製成的。"},{"en":"Synthetic data is used to train AI models.","zh-TW":"合成數據被用來訓練AI模型。"}]', '{"noun":"synthesis","adjective":"synthetic","verb":"synthesize"}', NULL, 3, 1999);